BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'activity_logs_pkey' AND conrelid = 'public.activity_logs'::regclass
  ) THEN
    ALTER TABLE ONLY public.activity_logs
      ADD CONSTRAINT activity_logs_pkey PRIMARY KEY (id);
  END IF;
END $$;


